 "content": "def transform(grid):
    """Expand each 3 into a small framed marker and a full-width baseline."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value != 3:
                continue
            # Cap above the marker.
            for x in range(c - 2, c + 3):
                if 0 <= r - 2 < h and 0 <= x < w:
                    out[r - 2][x] = 5
            # Central cap pixel and vertical frame.
            if 0 <= r - 1 < h and 0 <= c < w:
                out[r - 1][c] = 5
            for y in (r - 1, r, r + 1):
                for x in (c - 2, c + 2):
                    if 0 <= y < h and 0 <= x < w:
                        out[y][x] = 2
            # Full-width baseline two rows below, with a colored center segment.
            base = r + 2
            if 0 <= base < h:
                out[base] = [2] * w
                for x in range(max(0, c - 2), min(w, c + 3)):
                    out[base][x] = 8
    return out

